import { useState } from 'react';
import PlannerForm from './components/PlannerForm.jsx';
import MealPlan from './components/MealPlan.jsx';
import ShoppingList from './components/ShoppingList.jsx';
import { buildPlan } from './lib/planner.js';

export default function App() {
  const [plan, setPlan] = useState(null);

  function handleSubmit({ budget, familySize }) {
    setPlan(buildPlan({ budget, familySize }));
  }

  return (
    <main>
      <h1>Weekly Dinner Planner</h1>
      <PlannerForm onSubmit={handleSubmit} />
      {plan && (
        <>
          <MealPlan days={plan.days} totalCost={plan.totalCost} budget={plan.budget} valid={plan.valid} />
          <ShoppingList items={plan.shoppingList} />
        </>
      )}
    </main>
  );
}
