      "content": "// PDD: I/O contract + Success criteria — builds days[] and shoppingList[], validates budget.
import { MEALS } from './meals.js';

const DAYS_OF_WEEK = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

/**
 * @typedef {{ day: string, mealName: string, cost: number }} Day
 * @typedef {{ ingredient: string, qty: string, unitCost: number }} ShoppingItem
 * @typedef {{ days: Day[], shoppingList: ShoppingItem[], totalCost: number, budget: number, valid: boolean }} Plan
 */

/**
 * Build a weekly dinner plan.
 * Success criteria: 7 distinct meals, total cost <= budget.
 * @param {{ budget: number, familySize: number }} opts
 * @returns {Plan}
 */
export function buildPlan({ budget, familySize }) {
  // TODO(code-one-plus): "Success criteria" — meal selection is sequential over the fixed catalogue.
  // A future iteration could add preference/dietary filters (NEEDS_SOURCE_DECISION).
  const size = Math.max(1, familySize);

  /** @type {Day[]} */
  const days = MEALS.slice(0, 7).map((meal, i) => ({
    day: DAYS_OF_WEEK[i],
    mealName: meal.name,
    cost: parseFloat((meal.servingCostPerPerson * size).toFixed(2))
  }));

  const totalCost = parseFloat(days.reduce((sum, d) => sum + d.cost, 0).toFixed(2));

  // Deduplicate shopping list ingredients across all 7 meals
  const ingredientMap = {};
  MEALS.slice(0, 7).forEach(meal => {
    meal.ingredients.forEach(item => {
      const key = item.ingredient;
      if (!ingredientMap[key]) {
        ingredientMap[key] = { ...item };
      } else {
        // Accumulate unit cost if ingredient appears in multiple meals
        ingredientMap[key] = {
          ...ingredientMap[key],
          unitCost: parseFloat((ingredientMap[key].unitCost + item.unitCost).toFixed(2))
        };
      }
    });
  });

  /** @type {ShoppingItem[]} */
  const shoppingList = Object.values(ingredientMap);

  return {
    days,
    shoppingList,
    totalCost,
    budget,
    valid: totalCost <= budget
  };
}
